package com.storemate.backend.web;
import com.storemate.backend.domain.*;import com.storemate.backend.repo.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.transaction.annotation.Transactional;
import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @Transactional class InventoryBatchIntegrationTest {
 @Autowired InventoryController inventory;@Autowired AccountRepository accounts;@Autowired StoreRepository stores;@Autowired StoreMemberRepository members;@Autowired ProductRepository products;@Autowired StockBatchRepository batches;
 Account owner;Store store;
 @BeforeEach void setup(){String key=UUID.randomUUID().toString().substring(0,8);owner=accounts.save(new Account("batch-"+key,"unused-test-hash",Role.OWNER,"테스트 사장","20000101"));store=stores.save(new Store("테스트","기타",null,null,null,"09:00","22:00",key,owner));members.save(new StoreMember(owner,store,Role.OWNER,MemberStatus.APPROVED));}
 private Dto.ReceiptItem item(int count,LocalDate expiry){return new Dto.ReceiptItem("TEST-LOT","테스트 우유","기타",count,expiry==null?null:expiry.toString());}
 @Test void differentExpiriesRemainSeparateAndRetryDoesNotDoubleStock(){var request=new Dto.ReceiptRequest(List.of(item(3,LocalDate.now().minusDays(1)),item(7,LocalDate.now().plusDays(10))),"receipt-test-01");inventory.receive(owner,store.getId(),request);inventory.receive(owner,store.getId(),request);assertEquals(10,inventory.one(owner,store.getId(),"TEST-LOT").stock());assertEquals(2,inventory.batchList(owner,store.getId(),"TEST-LOT").size());inventory.discard(owner,store.getId(),"TEST-LOT");assertEquals(7,inventory.one(owner,store.getId(),"TEST-LOT").stock());assertEquals(LocalDate.now().plusDays(10).toString(),inventory.one(owner,store.getId(),"TEST-LOT").expiry());}
 @Test void legacyStockSurvivesFirstReceiptAndUnknownExpiryIsNotDiscarded(){products.save(new Product(store,"TEST-LOT","기존 우유","기타",5,0,null));inventory.receive(owner,store.getId(),new Dto.ReceiptRequest(List.of(item(2,LocalDate.now().minusDays(1))),"receipt-test-02"));inventory.discard(owner,store.getId(),"TEST-LOT");assertEquals(5,inventory.one(owner,store.getId(),"TEST-LOT").stock());assertNull(inventory.one(owner,store.getId(),"TEST-LOT").expiry());}
 @Test void changingPayloadWithSameReceiptKeyIsRejected(){inventory.receive(owner,store.getId(),new Dto.ReceiptRequest(List.of(item(2,null)),"receipt-test-03"));assertThrows(ApiException.class,()->inventory.receive(owner,store.getId(),new Dto.ReceiptRequest(List.of(item(3,null)),"receipt-test-03")));assertEquals(2,inventory.one(owner,store.getId(),"TEST-LOT").stock());}
 @Test void batchRevisionPreventsOverwritingAConcurrentEdit(){inventory.receive(owner,store.getId(),new Dto.ReceiptRequest(List.of(item(4,null)),"receipt-test-04"));var batch=inventory.batchList(owner,store.getId(),"TEST-LOT").getFirst();inventory.batchEdit(owner,store.getId(),"TEST-LOT",batch.id(),new InventoryController.BatchEdit(3,null,0L));assertThrows(ApiException.class,()->inventory.batchEdit(owner,store.getId(),"TEST-LOT",batch.id(),new InventoryController.BatchEdit(2,null,0L)));assertEquals(3,inventory.one(owner,store.getId(),"TEST-LOT").stock());}
 @Test void anotherAccountCannotReadStoreBatches(){var stranger=accounts.save(new Account("outsider-"+UUID.randomUUID().toString().substring(0,8),"unused",Role.STAFF,"외부 직원","20000101"));assertThrows(ApiException.class,()->inventory.batchList(stranger,store.getId(),"TEST-LOT"));}
 @Test void deletingProductHidesItAndKeepsHistoryBatchesAtZero(){inventory.receive(owner,store.getId(),new Dto.ReceiptRequest(List.of(item(4,LocalDate.now().plusDays(5))),"delete-product-01"));var original=products.findByStoreAndBarcode(store,"TEST-LOT").orElseThrow();inventory.delete(owner,store.getId(),"TEST-LOT",4);assertTrue(inventory.list(owner,store.getId()).isEmpty());assertThrows(ApiException.class,()->inventory.one(owner,store.getId(),"TEST-LOT"));assertTrue(original.isDeleted());assertEquals(0,original.getStock());assertEquals(1,batches.findByProductOrderByReceivedAtAscIdAsc(original).size());assertEquals(0,batches.findByProductOrderByReceivedAtAscIdAsc(original).getFirst().getQuantity());inventory.delete(owner,store.getId(),"TEST-LOT",4);}
 @Test void deletedBarcodeCanBeReceivedAgainWithoutOldStockReturning(){inventory.receive(owner,store.getId(),new Dto.ReceiptRequest(List.of(item(4,LocalDate.now().plusDays(5))),"delete-product-02"));inventory.delete(owner,store.getId(),"TEST-LOT",4);inventory.receive(owner,store.getId(),new Dto.ReceiptRequest(List.of(item(2,LocalDate.now().plusDays(10))),"delete-product-03"));assertEquals(2,inventory.one(owner,store.getId(),"TEST-LOT").stock());assertEquals(1,inventory.batchList(owner,store.getId(),"TEST-LOT").size());}
 @Test void changedStockAndOutsiderCannotDelete(){inventory.receive(owner,store.getId(),new Dto.ReceiptRequest(List.of(item(4,null)),"delete-product-04"));assertThrows(ApiException.class,()->inventory.delete(owner,store.getId(),"TEST-LOT",3));var stranger=accounts.save(new Account("delete-out-"+UUID.randomUUID().toString().substring(0,8),"unused",Role.STAFF,"외부 직원","20000101"));assertThrows(ApiException.class,()->inventory.delete(stranger,store.getId(),"TEST-LOT",4));assertEquals(4,inventory.one(owner,store.getId(),"TEST-LOT").stock());}
}
